expected.tests:
assert flatten_dict({'a':{'b':1},'c':2}) == {'a.b':1,'c':2}
assert flatten_dict({}) == {}
assert flatten_dict({'x':{'y':{'z':3}}}) == {'x.y.z':3}

assert parse_key_values('a=1 b=2') == {'a':'1','b':'2'}
assert parse_key_values('') == {}
assert parse_key_values('x=9 junk y=8') == {'x':'9','y':'8'}
